import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { createDashboard_v1 } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  mixins: [get_all_org_users],
  props: {
    dashboardCreation: Boolean
  },
  data() {
    return {
      loading: false,
      checkbit: true,
      dashboard_name: "",
      dashboardtype: "",
      subscription_id: "",
      userDetails: [],
      visibilityUsers: [],
      search: "",
      feedType: "",
      screatkey: "",
      idaccount: "",
      clientid: "",
      clientscret: "",
      awsAccountName: "",
      accesskey: "",
      dashboardVisbility: "ALL_MEMBERS",
      tenant_id: "",
      awscostobject: {},
      azureobject: {},
      visibilityobject: {},
      description: "",
      feedItems: [{
        name: "AWS Cost Monitor",
        value: "AWS_COST"
      }, {
        name: "Azure Cost Monitor",
        value: "AZURE_COST"
      }],
      broadcastFrequency: "",
      accountEmailId: ""
    };
  },
  watch: {
    dashboardCreation: {
      async handler() {
        if (this.dashboardCreation == true) {
          this.$store.commit("Setnamesearch", "");
          this.dashboardtype = null;
          this.broadcastFrequency = "";
          this.dashboardVisbility = "ALL_MEMBERS";
          await this.get_all_org_users();
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    convertToTimeZone(time) {
      let [hours, minutes] = time.split(":");
      let date = new Date();
      date.setUTCHours(parseInt(hours));
      date.setUTCMinutes(parseInt(minutes));
      let options = {
        // timeZone: "Asia/Kolkata",
        timeZone: this.$store.getters.GetOrgDetails.organization.default_timezone,
        hour: "2-digit",
        minute: "2-digit",
        hour12: true // 24-hour format
      };
      return new Intl.DateTimeFormat("en-US", options).format(date);
    },
    onuserinput(value) {
      if (!value.includes(this.$store.getters.GetUserObj.user.user_id)) {
        value.push(this.$store.getters.GetUserObj.user.user_id);
      }
      this.userDetails = value;
      this.search = "";
    },
    get_dashboard_name(value) {
      this.description = value;
    },
    fetch_details() {
      this.checkbit = false;
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && this.$store.getters.GetUserObj.user.user_id != element.user_id) {
          this.visibilityUsers.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    clear_value() {
      var data = this.$store.getters.GetUserObj;
      if (this.dashboardVisbility == "ALL_MEMBERS") {
        this.userDetails = [];
      } else {
        this.userDetails = [];
        this.visibilityUsers = [];
        this.orgUsers.forEach(element => {
          // if (element.user_id != data.user.user_id) {
          if (element.user_status == "ACTIVE") {
            this.visibilityUsers.push({
              full_user_name: element.full_user_name,
              user_id: element.user_id
            });
          }
          // }
        });
        this.userDetails.push(this.$store.getters.GetUserObj.user.user_id);
      }
    },
    close_dialog() {
      this.broadcastFrequency = "";
      this.$refs.form.reset();
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    async create_dashboard() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.awscostobject = {
          account_id: this.idaccount,
          accesskey: this.accesskey,
          account_name: this.awsAccountName,
          secretkey: this.screatkey
        };
        this.azureobject = {
          client_id: this.clientid,
          client_secrect: this.clientscret,
          subscription_id: this.subscription_id,
          tenant_id: this.tenant_id
        };
        // if (this.dashboardVisbility == "RESTRICTED_MEMBERS") {
        //   this.userDetails.push(this.$store.getters.GetUserObj.user.user_id);
        // }
        this.visibilityobject = {
          visible_type: this.dashboardVisbility,
          visible_members: this.userDetails
        },
        // console.log(this.visibilityobject, " this.visibilityobject");
        this.Createdash_board();
      }
    },
    async Createdash_board() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(createDashboard_v1, {
          input: {
            organization_id: data.organization.organization_id,
            dashboard_name: this.dashboard_name,
            user_email_id: data.user.user_email_id,
            dashboard_visibility: this.visibilityobject,
            dashboard_description: this.description,
            dashboard_publish_type: this.dashboardtype,
            dashboard_feed_type: this.dashboardtype == "FEED" ? this.feedType : undefined,
            dashboard_account_details: this.dashboardtype == "FEED" ? this.feedType == "AWS_COST" ? JSON.stringify(this.awscostobject) : JSON.stringify(this.azureobject) : undefined,
            broadcast_frequency: this.dashboardtype == "FEED" ? parseInt(this.broadcastFrequency) : undefined
          }
        }));
        var response = JSON.parse(result.data.createDashboard_v1);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "data");
          this.broadcastFrequency = "";
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        // console.log(error);
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
